{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2206-01-17 12:00:00",
      "speaker": "Doctor",
      "text": "Hello Mr. ___, I'm Dr. ___, your urology doctor. You're here today for your right percutaneous nephrolithotomy to treat the kidney stone. How are you feeling?"
    },
    {
      "turn_number": 2,
      "time": "2206-01-17 12:02:00",
      "speaker": "Patient",
      "text": "Hi doctor. I’m a bit nervous, but okay. The stone’s been causing a lot of discomfort lately."
    },
    {
      "turn_number": 3,
      "time": "2206-01-17 12:04:00",
      "speaker": "Doctor",
      "text": "I understand. The procedure is minimally invasive and should help relieve the blockage. We’ll place a small tube in your kidney to remove the stone fragments."
    },
    {
      "turn_number": 4,
      "time": "2206-01-17 12:06:00",
      "speaker": "Patient",
      "text": "Will I have another nephrostomy tube like before?"
    },
    {
      "turn_number": 5,
      "time": "2206-01-17 12:08:00",
      "speaker": "Doctor",
      "text": "Yes, a temporary one on the right side. It will drain urine and any stone fragments. The left tube is still in place from your last admission."
    },
    {
      "turn_number": 6,
      "time": "2206-01-17 12:10:00",
      "speaker": "Patient",
      "text": "Okay. And will I be in pain afterward?"
    },
    {
      "turn_number": 7,
      "time": "2206-01-17 12:12:00",
      "speaker": "Doctor",
      "text": "Some discomfort is normal. We’ll start with IV pain meds and switch to oral ones tomorrow. You’ll have acetaminophen and a narcotic for breakthrough pain."
    },
    {
      "turn_number": 8,
      "time": "2206-01-17 12:14:00",
      "speaker": "Patient",
      "text": "Got it. What about antibiotics?"
    },
    {
      "turn_number": 9,
      "time": "2206-01-17 12:16:00",
      "speaker": "Doctor",
      "text": "You’ll get IV antibiotics for 24 hours to prevent infection. After that, you’ll take fosfomycin once by mouth before discharge."
    },
    {
      "turn_number": 10,
      "time": "2206-01-17 12:18:00",
      "speaker": "Patient",
      "text": "I remember taking cipro before. Why the change?"
    },
    {
      "turn_number": 11,
      "time": "2206-01-17 12:20:00",
      "speaker": "Doctor",
      "text": "Because of past infections with resistant bacteria, we’re using fosfomycin this time—it works well for your history."
    },
    {
      "turn_number": 12,
      "time": "2206-01-17 12:22:00",
      "speaker": "Patient",
      "text": "Makes sense. Thank you."
    },
    {
      "turn_number": 13,
      "time": "2206-01-17 12:24:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll take you to the operating room shortly. The procedure should take a couple of hours."
    },
    {
      "turn_number": 14,
      "time": "2206-01-17 15:30:00",
      "speaker": "Doctor",
      "text": "Hi again. The procedure went well. We used fluoroscopy to guide the instruments and removed the stone fragments. No complications."
    },
    {
      "turn_number": 15,
      "time": "2206-01-17 15:32:00",
      "speaker": "Patient",
      "text": "That’s a relief. Is the tube in?"
    },
    {
      "turn_number": 16,
      "time": "2206-01-17 15:34:00",
      "speaker": "Doctor",
      "text": "Yes, the right nephrostomy tube is in place and draining. Your left tube and suprapubic catheter are also working well."
    },
    {
      "turn_number": 17,
      "time": "2206-01-17 15:36:00",
      "speaker": "Patient",
      "text": "Any blood in the urine?"
    },
    {
      "turn_number": 18,
      "time": "2206-01-17 15:38:00",
      "speaker": "Doctor",
      "text": "A little is expected. We’ll monitor it. You’re on IV pain meds now and will start drinking fluids soon."
    },
    {
      "turn_number": 19,
      "time": "2206-01-17 15:40:00",
      "speaker": "Patient",
      "text": "Okay. And the chest X-ray?"
    },
    {
      "turn_number": 20,
      "time": "2206-01-17 15:42:00",
      "speaker": "Doctor",
      "text": "We did a portable chest X-ray after surgery. Your lungs look clear, no fluid or infection. Everything is stable."
    },
    {
      "turn_number": 21,
      "time": "2206-01-17 15:44:00",
      "speaker": "Patient",
      "text": "Good to hear."
    },
    {
      "turn_number": 22,
      "time": "2206-01-18 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. How’s your pain today?"
    },
    {
      "turn_number": 23,
      "time": "2206-01-18 08:02:00",
      "speaker": "Patient",
      "text": "Better. I took Tylenol this morning and it helped."
    },
    {
      "turn_number": 24,
      "time": "2206-01-18 08:04:00",
      "speaker": "Doctor",
      "text": "Great. We checked your labs this morning—your hemoglobin is stable, and kidney function is normal."
    },
    {
      "turn_number": 25,
      "time": "2206-01-18 08:06:00",
      "speaker": "Patient",
      "text": "Any sign of infection?"
    },
    {
      "turn_number": 26,
      "time": "2206-01-18 08:08:00",
      "speaker": "Doctor",
      "text": "No fever, and your white blood cell count is normal. You finished the IV antibiotics, so you’re on track."
    },
    {
      "turn_number": 27,
      "time": "2206-01-18 08:10:00",
      "speaker": "Patient",
      "text": "Can I eat normally?"
    },
    {
      "turn_number": 28,
      "time": "2206-01-18 08:12:00",
      "speaker": "Doctor",
      "text": "Yes, you tolerated your diet yesterday, so keep with your regular home diet. Drink plenty of fluids."
    },
    {
      "turn_number": 29,
      "time": "2206-01-18 08:14:00",
      "speaker": "Patient",
      "text": "I will. What about the tube?"
    },
    {
      "turn_number": 30,
      "time": "2206-01-18 08:16:00",
      "speaker": "Doctor",
      "text": "We’ll clamp it this morning to see if your kidney can drain on its own. If you stay pain-free, we’ll remove it this afternoon."
    },
    {
      "turn_number": 31,
      "time": "2206-01-18 10:30:00",
      "speaker": "Doctor",
      "text": "The tube has been clamped for a couple of hours. Any pain or discomfort?"
    },
    {
      "turn_number": 32,
      "time": "2206-01-18 10:32:00",
      "speaker": "Patient",
      "text": "None at all."
    },
    {
      "turn_number": 33,
      "time": "2206-01-18 10:34:00",
      "speaker": "Doctor",
      "text": "That’s excellent. We’ll remove the right nephrostomy tube now. The left one stays for now."
    },
    {
      "turn_number": 34,
      "time": "2206-01-18 11:00:00",
      "speaker": "Doctor",
      "text": "Tube is out. The site is clean and not bleeding. You’re doing very well."
    },
    {
      "turn_number": 35,
      "time": "2206-01-18 11:02:00",
      "speaker": "Patient",
      "text": "Thank you. What do I need to do at home?"
    },
    {
      "turn_number": 36,
      "time": "2206-01-18 11:04:00",
      "speaker": "Doctor",
      "text": "You’ll keep the left nephrostomy tube for now. Flush it twice daily with saline, change the dressing every day, and monitor urine output."
    },
    {
      "turn_number": 37,
      "time": "2206-01-18 11:06:00",
      "speaker": "Patient",
      "text": "And the pain meds?"
    },
    {
      "turn_number": 38,
      "time": "2206-01-18 11:08:00",
      "speaker": "Doctor",
      "text": "Use Tylenol first. If pain is above 4, take the narcotic. But don’t exceed 4 grams of Tylenol a day—remember it’s in the narcotic too."
    },
    {
      "turn_number": 39,
      "time": "2206-01-18 11:10:00",
      "speaker": "Patient",
      "text": "Got it. And follow-up?"
    },
    {
      "turn_number": 40,
      "time": "2206-01-18 11:12:00",
      "speaker": "Doctor",
      "text": "You’ll have a visiting nurse to help with the tube. And you’re scheduled for the left-side procedure in a few weeks."
    },
    {
      "turn_number": 41,
      "time": "2206-01-18 11:14:00",
      "speaker": "Patient",
      "text": "Okay. Any warning signs I should watch for?"
    },
    {
      "turn_number": 42,
      "time": "2206-01-18 11:16:00",
      "speaker": "Doctor",
      "text": "Yes—call if you have fever over 101.5, worsening pain, heavy bleeding, or trouble breathing. And don’t drive while on narcotics."
    },
    {
      "turn_number": 43,
      "time": "2206-01-18 11:18:00",
      "speaker": "Patient",
      "text": "I’ll be careful. Thanks for everything."
    },
    {
      "turn_number": 44,
      "time": "2206-01-18 11:20:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll get your discharge papers ready. You’re doing great."
    },
    {
      "turn_number": 45,
      "time": "2206-01-18 14:00:00",
      "speaker": "Doctor",
      "text": "Just a final check before discharge. Pain still controlled?"
    },
    {
      "turn_number": 46,
      "time": "2206-01-18 14:02:00",
      "speaker": "Patient",
      "text": "Yes, just mild soreness."
    },
    {
      "turn_number": 47,
      "time": "2206-01-18 14:04:00",
      "speaker": "Doctor",
      "text": "Perfect. You’re cleared to go home. The nurse will review all instructions again."
    },
    {
      "turn_number": 48,
      "time": "2206-01-18 14:06:00",
      "speaker": "Patient",
      "text": "Appreciate it."
    },
    {
      "turn_number": 49,
      "time": "2206-01-18 14:08:00",
      "speaker": "Doctor",
      "text": "Take care, and we’ll see you soon for the next step."
    },
    {
      "turn_number": 50,
      "time": "2206-01-18 14:10:00",
      "speaker": "Patient",
      "text": "Looking forward to it. Bye for now."
    }
  ],
  "summary": {
    "admission_start": "2206-01-17 11:30:00",
    "admission_end": "2206-01-18 18:18:00",
    "summary_paragraph": "Mr. ___, a man with primary progressive multiple sclerosis and neurogenic bladder managed with a suprapubic catheter, was admitted for a right percutaneous nephrolithotomy due to bilateral kidney stones. The procedure was performed without complications, and a temporary nephrostomy tube was placed on the right side. He received intravenous antibiotics for 24 hours and was transitioned to oral pain control with acetaminophen and a narcotic for breakthrough pain. The right nephrostomy tube was clamped and subsequently removed on postoperative day one after he remained pain-free. He tolerated a regular diet, had stable labs, and no signs of infection. He was discharged home with instructions to care for the remaining left nephrostomy tube, continue fosfomycin, monitor for complications, and prepare for the left-sided procedure in the coming weeks.",
    "problems": [
      "Urinary calculus, unspecified",
      "Multiple sclerosis",
      "Neuromuscular dysfunction of bladder, unspecified",
      "Retention of urine, unspecified",
      "Cramp and spasm",
      "Dependence on wheelchair",
      "Other artificial openings of urinary tract status",
      "Colostomy status",
      "Major depressive disorder, single episode, unspecified",
      "Age-related osteoporosis without current pathological fracture",
      "Intestinal bypass and anastomosis status",
      "Gastro-esophageal reflux disease without esophagitis"
    ]
  }
}
